<template>
  <div><PageHeader eyebrow="GRADEBOOK" :title="auth.role === 'student' ? 'Điểm số' : 'Sổ điểm'" :description="auth.role === 'student' ? 'Chỉ điểm đã publish mới được hiển thị trong workspace của bạn.' : 'Theo dõi điểm theo từng grade item, giữ audit khi điều chỉnh.'"><template #actions><RouterLink v-if="auth.role !== 'student'" class="button secondary" to="/reports">Mở báo cáo</RouterLink></template></PageHeader><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><div class="toolbar"><select v-model="selectedClassId" class="form-select" style="max-width:340px"><option value="">Chọn lớp học</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select><span class="cell-subtle">{{ gradebook?.items.length || 0 }} grade items</span></div><section v-if="editingItem" class="panel" style="margin-bottom:16px"><form class="inline-form" @submit.prevent="saveWeight"><div><strong>{{ editingItem.title }}</strong><span class="cell-subtle">Trọng số từ 0 đến 100</span></div><input v-model.number="weightForm" class="form-input" type="number" min="0" max="100" step="0.01" required /><button class="button primary" :disabled="weightBusy">{{ weightBusy ? 'Đang lưu…' : 'Lưu trọng số' }}</button><button type="button" class="mini-button" @click="editingItem = null">Đóng</button></form></section><div v-if="loading" class="loading-state">Đang tải sổ điểm…</div><section v-else-if="gradebook" class="panel"><div class="panel-heading"><h2>{{ auth.role === 'student' ? 'Kết quả đã công bố' : 'Gradebook view' }}</h2><span>{{ gradebook.students.length }} người học</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th v-if="auth.role !== 'student'">Student</th><th v-for="item in gradebook.items" :key="item.gradeItemId">{{ item.title }}<span class="cell-subtle">{{ item.maxScore }} điểm · {{ item.weight }}</span><button v-if="auth.role !== 'student'" class="mini-button" @click="editWeight(item)">Sửa trọng số</button></th><th>Trung bình</th></tr></thead><tbody><tr v-for="student in visibleStudents" :key="student.studentId"><td v-if="auth.role !== 'student'"><span class="cell-primary">{{ student.studentId.slice(0, 8) }}</span></td><td v-for="item in gradebook.items" :key="item.gradeItemId"><span class="cell-primary">{{ score(student, item.gradeItemId) }}</span><span class="cell-subtle">{{ gradeStatus(student, item.gradeItemId) }}</span></td><td><strong>{{ student.finalScore ?? student.weightedAverage ?? student.average ?? '—' }}</strong></td></tr></tbody></table></div><div v-if="!visibleStudents.length" class="empty-state"><strong>Chưa có điểm</strong><span>Điểm sẽ xuất hiện sau khi teacher chấm và publish.</span></div></section><div v-else class="panel empty-state"><strong>Chọn lớp học</strong><span>Chọn lớp để tải gradebook theo quyền của bạn.</span></div></div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import PageHeader from '../../../shared/ui/PageHeader.vue'; import { useAuthStore } from '../../../shared/stores/auth'; import { academicsApi, assessmentApi, gradingApi } from '../../../shared/api/client'; import type { Gradebook, GradebookItem, GradebookStudent, LearningClass } from '../../../shared/types'
const auth = useAuthStore(); const classes = ref<LearningClass[]>([]); const selectedClassId = ref(''); const gradebook = ref<Gradebook | null>(null); const loading = ref(true); const error = ref(''); const editingItem = ref<GradebookItem | null>(null); const weightForm = ref(1); const weightBusy = ref(false); const visibleStudents = computed(() => auth.role === 'student' ? gradebook.value?.students.slice(0, 1) || [] : gradebook.value?.students || [])
function entries(student: GradebookStudent) { return student.entries || student.cells || [] }; function score(student: GradebookStudent, id: string) { return entries(student).find(item => item.gradeItemId === id)?.score ?? '—' }; function gradeStatus(student: GradebookStudent, id: string) { return entries(student).find(item => item.gradeItemId === id)?.status || 'Chưa publish' }
async function load() { if (!selectedClassId.value) { gradebook.value = null; loading.value = false; return }; loading.value = true; try { gradebook.value = await assessmentApi.gradebook(selectedClassId.value, auth.role === 'student') } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được sổ điểm.') } finally { loading.value = false } }
function editWeight(item: GradebookItem) { editingItem.value = item; weightForm.value = Number(item.weight) }
async function saveWeight() { if (!editingItem.value) return; weightBusy.value = true; try { await gradingApi.updateGradeItem(editingItem.value.gradeItemId, weightForm.value); editingItem.value = null; await load() } catch (cause) { error.value = String((cause as Error)?.message || 'Không cập nhật được trọng số.') } finally { weightBusy.value = false } }
async function boot() { try { classes.value = await academicsApi.classes(); if (classes.value[0]) selectedClassId.value = classes.value[0].id } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được lớp học.'); loading.value = false } }
watch(selectedClassId, load); onMounted(boot)
</script>
